--PR 41738:Redesigned the query as per attachment "115000357_mike.sql" --PR 42381:Kalyan:26 Feb 2010: --1. The join in FROM clause is changed using "@MINER@.acct b" --2. Four filters for Acct are added to WHERE clause --3.Moved KDD_CAL from inner join to WHERE clause --OFSAABD-10760 with included_acct as ( -- Find all accounts that have at least one wire in the frequency period SELECT distinct a.ACCT_INTRL_ID, a.acct_efctv_risk_nb FROM @MINER@.ACCT a, @MINER@.cash_trxn c where --Include Customer Retail Accounts Only a.mantas_acct_holdr_type_cd = 'CR' --Exclude Exempt Accounts and a.acct_efctv_risk_nb <> -2 and (@All_Jurisdictions_Fl = 'Y' or a.jrsdcn_cd in (@Incl_Jurisdictions_Lst)) and (@All_Trans_Src_Fl = 'Y' or c.src_sys_cd in (@Incl_Trans_Src_Lst)) and a.mantas_acct_bus_type_cd in (@Mantas_Bus_Acct_Type_Lst) and c.data_dump_dt > (select add_days(cal.clndr_dt, -@Frequency_Period) from @MANTAS@.KDD_cal cal where cal.clndr_day_age = 0 and cal.clndr_nm = 'SYSCAL') and c.data_dump_dt <= (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.clndr_day_age = 0 and cal.clndr_nm = 'SYSCAL') --Exclude Electronic Funds Transactions between Related Parties and (@Incl_Rltd_Parties = 'Y' or coalesce(c.unrltd_party_fl, 'Y') <> 'N') and a.acct_intrl_id = c.acct_intrl_id and c.MANTAS_TRXN_PRDCT_CD in (@Incl_Cash_Trxn_Prdct_Type_Lst) and c.dbt_cdt_cd = 'C' --28912810 and c.MANTAS_TRXN_PURP_CD = 'GENERAL' --28039975 --Exclude Canceled and Canceling Transactions and c.CXL_PAIR_TRXN_INTRL_ID IS NULL
)
select cash.acct_intrl_id d_acct_id, DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) d_trxn_base_amt, (select f_to_number(f_date_to_char(clndr_dt, 'J')) from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') d_clndr_dt, cash.fo_trxn_seq_id, f_to_number(f_date_to_char(cash.data_dump_dt, 'J')) d_data_dump_dt, case when cash.cash_trxn_actvy_risk_nb > 0 or cash.cash_trxn_ntity_risk_nb > 0 then DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) else 0 end d_hr_trxn_am, 0 d_pass_thru_trxn_am, case when DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) - trunc(DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM), -@Lrf_Digits) = 0 then DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) when cash.trxn_actvy_am - trunc(cash.trxn_actvy_am, -@Lrf_Digits) = 0 then DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) else 0 end d_lrf_trxn_am, 0 as d_Trusted_Trans_Amt, cash.FUNC_CRNCY_CD from @MINER@.cash_trxn cash, included_acct a where cash.acct_intrl_id = a.acct_intrl_id and cash.MANTAS_TRXN_PRDCT_CD in (@Incl_Cash_Trxn_Prdct_Type_Lst) and cash.dbt_cdt_cd = 'C' and ( (a.acct_efctv_risk_nb >= @Effctv_Risk_Cutoff_Lvl and DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) >= @HR_Min_Indiv_Trans_Amt) or (a.acct_efctv_risk_nb < @Effctv_Risk_Cutoff_Lvl and DECODE(@Curr_Type,'F',cash.TRXN_FUNC_AM,cash.TRXN_BASE_AM) >= @RR_Min_Indiv_Trans_Amt) ) --Exclude Cash Transactions between Related Parties and (@Incl_Rltd_Parties = 'Y' or coalesce(cash.unrltd_party_fl, 'Y') <> 'N') and cash.trxn_exctn_dt > (select add_days(clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and cash.trxn_exctn_dt <= (select clndr_dt from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') --29264775 and cash.data_dump_dt > (select add_days(clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and cash.data_dump_dt <= (select clndr_dt from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and (@All_Trans_Src_Fl = 'Y' or cash.src_sys_cd in (@Incl_Trans_Src_Lst)) --28912810 and cash.MANTAS_TRXN_PURP_CD = 'GENERAL' --28039975 --Exclude Canceled and Canceling Transactions and cash.CXL_PAIR_TRXN_INTRL_ID IS NULL

