t from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and (@All_Trans_Src_Fl = 'Y' or cash.src_sys_cd in (@Incl_Trans_Src_Lst)) --28912810 and cash.MANTAS_TRXN_PURP_CD = 'GENERAL' --28039975 --Exclude Canceled and Canceling Transactions and cash.CXL_PAIR_TRXN_INTRL_ID IS NULL

--PR 41738:Redesigned the query as per attachment "115000432_mike.sql" --PR 42381:Kalyan:26 Feb 2010: --1. The join in FROM clause is changed using "BUSINESS.acct b" --2. Four filters for Acct are added to WHERE clause --3.Replaced NVL by Coalesce and Moved KDD_CAL from inner join to WHERE clause --OFSAABD-10760 --Bug30688333 with included_acct as ( -- Find all accounts that have at least one MI in the frequency period SELECT distinct a.ACCT_INTRL_ID, a.acct_efctv_risk_nb FROM @MINER@.ACCT a, @MINER@.mi_trxn mi where --Include Customer Retail Accounts Only a.mantas_acct_holdr_type_cd = 'CR' --Exclude Exempt Accounts and a.acct_efctv_risk_nb <> -2 and (@All_Jurisdictions_Fl = 'Y' or a.jrsdcn_cd in (@Incl_Jurisdictions_Lst)) and (@All_Trans_Src_Fl = 'Y' or mi.src_sys_cd in (@Incl_Trans_Src_Lst)) and a.mantas_acct_bus_type_cd in (@Mantas_Bus_Acct_Type_Lst) and mi.data_dump_dt > (select add_days(cal.clndr_dt, -@Frequency_Period) from @MANTAS@.KDD_cal cal where cal.clndr_day_age = 0 and cal.clndr_nm = 'SYSCAL') and mi.data_dump_dt <= (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.clndr_day_age = 0 and cal.clndr_nm = 'SYSCAL') --Exclude Monetary Instrument Transactions between Related Parties and (@Incl_Rltd_Parties = 'Y' or coalesce(mi.unrltd_party_fl, 'Y') <> 'N') --Include all Monetary Instrument Transactions except Travelers Check Transactions --Bug30688333 and mi.mantas_trxn_prdct_cd <> ('CASH-EQ-TRAVELERS-CHECK') and a.acct_intrl_id = mi.rem_acct_id and mi.mantas_trxn_prdct_cd in (@Incl_MI_Trxn_Prdct_Type_Lst) and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(mi.TRSTD_TRXN_FL,'N') ='N') --Include Bank-to-Bank Transactions and (@Include_B2B_Trnfr_Fl = 'Y' or NOT(mi.BANK_TO_BANK_TRNFR_FL = 'Y' and mi.PASS_THRU_FL = 'N')) --28912810 and mi.MANTAS_TRXN_PURP_CD = 'GENERAL' --28039975 --Exclude Canceled and Canceling Transactions and mi.CXL_PAIR_TRXN_INTRL_ID IS NULL
) -- MIs with the focus account as beneficiary select mi.rem_acct_id d_acct_id, DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) d_trxn_base_amt, (select f_to_number(f_date_to_char(clndr_dt, 'J')) from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') d_clndr_dt, mi.fo_trxn_seq_id, f_to_number(f_date_to_char(mi.data_dump_dt, 'J')) d_data_dump_dt, case when mi.rem_ntity_risk_nb > 0 or mi.rem_actvy_risk_nb > 0 then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) else 0 end d_hr_trxn_am, case when mi.pass_thru_fl = 'Y' then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) else 0 end d_pass_thru_trxn_am, case when DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) - trunc(DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM), -@Lrf_Digits) = 0 then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) when mi.clr_trxn_actvy_am - trunc(mi.clr_trxn_actvy_am, -@Lrf_Digits) = 0 then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) when mi.dep_trxn_actvy_am - trunc(mi.dep_trxn_actvy_am, -@Lrf_Digits) = 0 then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) when mi.issue_trxn_actvy_am - trunc(mi.issue_trxn_actvy_am, -@Lrf_Digits) = 0 then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) else 0 end d_lrf_trxn_am, case when mi.TRSTD_TRXN_FL = 'Y' then DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) else 0 end as d_Trusted_Trans_Amt, mi.FUNC_CRNCY_CD
from @MINER@.mi_trxn mi, included_acct a where mi.rem_acct_id = a.ACCT_INTRL_ID and mi.mantas_trxn_prdct_cd in (@Incl_MI_Trxn_Prdct_Type_Lst) and mi.rem_acct_id is not null and mi.intrl_rem_acct_fl = 'Y' and ( (a.acct_efctv_risk_nb >= @Effctv_Risk_Cutoff_Lvl and DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) >= @HR_Min_Indiv_Trans_Amt) or (a.acct_efctv_risk_nb < @Effctv_Risk_Cutoff_Lvl and DECODE(@Curr_Type,'F',mi.TRXN_FUNC_AM,mi.TRXN_BASE_AM) >= @RR_Min_Indiv_Trans_Amt) ) --Exclude Monetary Instrument Transactions between Related Parties and (@Incl_Rltd_Parties = 'Y' or coalesce(mi.unrltd_party_fl, 'Y') <> 'N') --Include all Monetary Instrument Transactions except Travelers Check Transactions --Bug30688333 and mi.mantas_trxn_prdct_cd <> ('CASH-EQ-TRAVELERS-CHECK') and mi.mantas_issue_date > (select add_days(clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and mi.mantas_issue_date <= (select clndr_dt from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') --29264775 and mi.data_dump_dt > (select add_days(clndr_dt, -@Look_Back_Period) from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and mi.data_dump_dt <= (select clndr_dt from @MANTAS@.KDD_cal where clndr_day_age = 0 and clndr_nm = 'SYSCAL') and (@All_Trans_Src_Fl = 'Y' or mi.src_sys_cd in (@Incl_Trans_Src_Lst)) and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(mi.TRSTD_TRXN_FL,'N') ='N') --Include Bank-to-Bank Transactions and (@Include_B2B_Trnfr_Fl = 'Y' or NOT(mi.BANK_TO_BANK_TRNFR_FL = 'Y' and mi.PASS_THRU_FL = 'N')) --28912810 and mi.MANTAS_TRXN_PURP_CD = 'GENERAL' --28039975 --Exclude Canceled and Canceling Transactions and mi.CXL_PAIR_TRXN_INTRL_ID IS NULL
